def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 5:
        return 'C'
    opp_ever_c = False
    for _, o in history:
        if o == 'C':
            opp_ever_c = True
            break
    if not opp_ever_c:
        return 'D'
    last_my, last_opp = history[-1]
    if last_my == 'D' and last_opp == 'C':
        return 'D'
    if n >= 10:
        all_c = True
        for a, b in history:
            if a != 'C' or b != 'C':
                all_c = False
                break
        if all_c:
            return 'D'
    if last_opp == 'C':
        return 'C'
    if n >= 2 and last_my == 'C' and history[-2][0] == 'D':
        return 'C'
    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break
    if def_streak >= 2:
        return 'D'
    return 'C'
